"""Readable supplement generated only from completed audited measurements."""
from pathlib import Path
import json,csv,html
from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,Table,TableStyle,PageBreak,Image,KeepTogether
from reportlab.lib import colors
from reportlab.lib.styles import getSampleStyleSheet,ParagraphStyle
from reportlab.lib.enums import TA_LEFT
from reportlab.lib.pagesizes import A4
ROOT=Path(__file__).resolve().parent
def read(name):return list(csv.DictReader((ROOT/'analysis'/name).open(newline='',encoding='utf-8')))
def main():
 audit=json.loads((ROOT/'checks/all_run_audit.json').read_text());assert audit['passed'];verdict=json.loads((ROOT/'analysis/verdict.json').read_text());s=read('summary.csv');pairs=read('paired_capture_comparisons.csv');styles=getSampleStyleSheet();styles.add(ParagraphStyle(name='SmallBody',fontName='Helvetica',fontSize=9,leading=12,spaceAfter=6));styles.add(ParagraphStyle(name='TinyBody',fontName='Helvetica',fontSize=7.5,leading=9.5));styles['Title'].fontSize=19;styles['Title'].leading=23;styles['Heading1'].fontSize=13;styles['Heading1'].leading=17
 content=[];P=lambda t:Paragraph(t,styles['SmallBody']);T=lambda t:Paragraph(t,styles['TinyBody']);H=lambda t:Paragraph(t,styles['Heading1'])
 names={'dos_main':'DoS15 (old)','bot_main':'Bot02 (old)','dos16_new':'Hulk16 (new)','ddos20_new':'DDoS20 (new)'};labels={'new_selected':'GDT','matched_verified':'Verified-only','simple_max':'Maximum','frozen_detector':'Frozen','arf_native_matched':'Native ARF'}
 def table(rows,widths):
  obj=Table([[T(str(c)) for c in row] for row in rows],colWidths=widths,repeatRows=1,hAlign='LEFT');obj.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#e8eef3')),('LINEBELOW',(0,0),(-1,0),.7,colors.HexColor('#163047')),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),5),('RIGHTPADDING',(0,0),(-1,-1),5),('TOPPADDING',(0,0),(-1,-1),3),('BOTTOMPADDING',(0,0),(-1,-1),3),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#f5f7f9')]) ]));return obj
 content += [Paragraph('Adaptive IDS: matched-baseline and new-capture supplement',styles['Title']),P('Gilang Wasis Wicaksono and Vera Suryani | 26 November 2026'),P('Frozen D5 extension of the D4 study. New evidence uses two previously unscored capture members; old-capture ARF comparisons are retrospective additions. All annotations are simulated.'),H('1. Measured performance')]
 rows=[['Capture','System','BA %','Recall %','FPR %','AP','Source change pp']]
 for ds in names:
  for policy in labels:
   r=next(r for r in s if r['dataset']==ds and r['policy']==policy);rows.append([names[ds],labels[policy],f"{100*float(r['balanced_accuracy_mean']):.2f}",f"{100*float(r['recall_mean']):.2f}",f"{100*float(r['fpr_mean']):.2f}",f"{float(r['AP_mean']):.3f}",f"{float(r['source_change_pp_mean']):+.2f}"])
 content += [table(rows,[83,88,47,53,48,42,82]),Spacer(1,9),P('Means average four feedback conditions within each seed, then five seeds. BA = balanced accuracy; AP = average precision. Source change compares the final controlled decision score with the initial raw primary model; it is not forgetting across all tasks. ARF uses the same labels and audits but native unweighted updates; HGB uses replay and 1/4/8 weights.'),PageBreak()]
 content += [H('2. Incremental gate-path evidence'),Image(str(ROOT/'analysis/figures/paired_gate_comparisons.png'),width=493,height=201)]
 rows=[['Capture','Comparator','GDT - comparator BA pp','95% paired interval']]
 for ds in names:
  for comparator in ['matched_verified','simple_max','arf_native_matched','frozen_detector']:
   r=next(r for r in pairs if r['dataset']==ds and r['comparator']==comparator);rows.append([names[ds],labels[comparator],f"{float(r['balanced_accuracy_difference']):+.2f}",f"[{float(r['balanced_accuracy_ci_low']):+.2f}, {float(r['balanced_accuracy_ci_high']):+.2f}]"])
 content += [table(rows,[90,100,144,159]),Spacer(1,8),P('Intervals use five paired seed differences (df = 4), after averaging four conditions per seed. They are unadjusted, capture-specific algorithmic intervals; neither flows nor seeds represent independent organizations. The one-point incremental target also requires acceptable source/FPR gaps. Comparing GDT with ARF is a detector-package comparison; the cleaner gate attribution is GDT versus verified-only.'),PageBreak()]
 content += [H('3. Coverage, tradeoffs, and prespecified targets'),Image(str(ROOT/'analysis/figures/gate_coverage.png'),width=493,height=172)]
 for ds in ['dos16_new','ddos20_new']:
  v=verdict[ds];content.append(P(f"<b>{names[ds]}:</b> gate gain over verified-only {v['gate_vs_verified_BA_pp']:+.2f} pp; gate gain over maximum {v['gate_vs_max_BA_pp']:+.2f} pp; gate gain over native ARF {v['gate_vs_ARF_BA_pp']:+.2f} pp. Incremental target met: {v['gate_increment_target_met']}. Package adaptation criteria met: {v['adaptation_criteria_met']}."))
 content += [P('<b>Consistent incremental gate benefit on both new captures:</b> '+str(verdict['consistent_gate_increment_on_both_new_captures'])+'. This conclusion must not be replaced by the easier comparison with a frozen detector or a weaker baseline.'),P('The original D4 criteria remain: adaptation BA gain at least 2 pp over frozen, source loss no greater than 2 pp, and FPR no greater than 2%. Gate criteria require at least 1 pp over verified-only, source gap no worse than -2 pp, FPR gap no greater than 1 pp, and positive lower paired interval on both new captures for a consistency claim.'),P('A high precision among gate changes can coexist with negligible benefit when few decisions change. Gate rescues and additional false positives are counted at the same raw cut 0.5; full system comparisons also include the induced audit-threshold path. Detailed family, per-condition, and FPR-budget files accompany the measurements.'),Image(str(ROOT/'analysis/figures/capture_performance.png'),width=493,height=194),PageBreak()]
 content += [H('4. Protocol, reproducibility, and limits')]
 for ds in ['dos16_new','ddos20_new']:
  d=json.loads((ROOT/f'data/{ds}_preparation.json').read_text());content.append(P(f"<b>{names[ds]}:</b> {d['member']}; {d['raw_rows']:,} scanned rows, {d['records']:,} selected flows, {d['binary_counts'].get('1',0):,} attacks. Selection was label-blind after predictor deduplication/conflict and overlap removal. Time order follows recorded flow timestamps. Member CRC {d['member_crc32']}; streamed CSV SHA256: {d['streamed_csv_sha256']}."))
 paragraphs=[
 'The selected GDT configuration, source-only transformations, and final S3 retention probes are unchanged. Five seeds (11, 23, 37, 51, 79) and four feedback conditions were locked before scoring the new captures. The conditions are correct delay 1, correct delay 80, 10% wrong labels corrected 400 events after arrival, and evaluator-injected corruption of 25% of attack-side ML2 proposals under delay 80.',
 'Both learners predict the entire 100-flow block before processing arrived feedback. Query identities are exactly shared: 5 requests per 100 flows, including 4 training and 1 audit. Only arrived training labels update classifiers; audits tune thresholds from originally issued scores using the same grid, window, minimum count, and 4FN+FP objective.',
 'Native ARF uses River 0.22.0 defaults: 10 trees, sqrt feature subspaces, Poisson lambda 6, ADWIN drift/warning detectors, and adaptive naive-Bayes leaves. Each new arrived training label is learned once at the next block boundary. On a changed previously learned target, restore the initial source model and replay all arrived labels in first-arrival order using latest revisions. This is a correction adapter, not a claim that ARF natively deletes labels.',
 'HGB instead refits every 200 flows or after a used-target correction, with bounded replay and source/new-benign/new-attack weights 1/4/8. ARF external sample weights are not supported by the pinned forest wrapper. Native ARF therefore differs in weighting, update cadence, and state retention. Neither equal computation nor a pure learner-only causal effect is claimed.',
 f"Audit: {audit['system_evaluations_audited']} extension system evaluations passed; {audit['native_ARF_feedback_schedules_matched']} ARF schedules exactly match the acquisition engine; {audit['ARF_training_label_uses_checked']:,} ARF label uses were checked; audit labels used for training: 0. All {audit['D4_original_lock_files_unchanged']} original locked D4 files remain unchanged. Routing reconstruction also matched 120 original control traces exactly.",
 f"There is no overlap with the previously sampled 2018 cohorts. The two new captures share {audit['new_capture_cross_overlap_fingerprints']} predictor fingerprints; they are not fully independent populations. Both also belong to the same historical benchmark/testbed. Large positive support on Hulk does not resolve SQL or sparse-attack failures on the original cohorts.",
 'The extension adds 80 native-ARF runs and 40 shared HGB/NN trajectories, producing 240 additional system evaluations. Together with 160 reused original evaluations, the comparison matrix contains 400 rows; these are correlated evaluations, not 400 independent datasets. Source training caches and all prediction/feedback records accompany the frozen source package.',
 'No real-human review accuracy, production latency, multi-organization generalization, new base learner, or universal superiority is established. No parameter replacement or test-based retuning was performed. Future improvements must use a separate development stage and another untouched confirmation set.'
 ]
 content.extend(P(p) for p in paragraphs)
 content += [P('Baseline documentation: <link href="https://riverml.xyz/0.22.0/api/forest/ARFClassifier/">River ARFClassifier 0.22.0</link>. Corrected benchmark: <link href="https://intrusion-detection.distrinet-research.be/CNS2022/">author documentation</link>. Original public study: <link href="https://github.com/langss1/verified-feedback-adaptive-ids">code and artifacts</link>.')]
 def footer(c,doc):c.setFont('Helvetica',8);c.setFillColor(colors.HexColor('#526170'));c.drawString(42,24,'D5 supplement | simulated feedback | frozen configuration');c.drawRightString(A4[0]-42,24,str(doc.page))
 content += [PageBreak(),H('5. Learning progress of both models'),Image(str(ROOT/'analysis/figures/all_role_learning_curves.png'),width=493,height=272),P('Cumulative attack recall under delay 80, averaged across five seeds, versus arrived training labels. ML1 and ML2 use raw scores at cut 0.5; GDT uses its issued controller-adjusted decision score. Pre-update mistakes remain counted. Empty-positive prefixes are undefined and omitted, not replaced by 100% recall.'),P('Hulk16 and DDoS20 have much more positive support than the original DoS15 sample. Their stronger adaptation does not imply that rare attacks recover equally well. The original SQL failure remains, and the new DDoS-LOIC-UDP family has only one positive flow, so its family-level result is descriptive.'),P('AP in the main performance table uses issued threshold-shifted scores; raw-score metrics are supplied separately. The post-hoc overlap sensitivity removes 63 shared fingerprints from evaluation only while retaining original learner state. It does not remove prior training influence. Primary metrics and verdicts continue to use the full locked cohorts.'),P('A separate-process replay rebuilt the initial HGB and ARF models, reran the new Hulk16 seed-11 corrected-feedback case, and exactly matched both target and source prediction hashes. The ARF correction adapter performed 41 resets in that case. All run-level hash receipts and logs are included in the extension bundle.')]
 pdf=ROOT/'D5_Baseline_and_New_Capture_Supplement.pdf';SimpleDocTemplate(str(pdf),pagesize=A4,rightMargin=42,leftMargin=42,topMargin=38,bottomMargin=40,title='Matched ARF and new-capture adaptive IDS evaluation',author='Gilang Wasis Wicaksono and Vera Suryani').build(content,onFirstPage=footer,onLaterPages=footer);print(pdf)
if __name__=='__main__':main()
